<script setup lang="ts">
import {ask} from './confirm';
import {ref,onMounted,watch,computed,onUnmounted} from 'vue';import {api,ApiError} from './api';import Dialog from './Dialog.vue';import SchemaForm from './SchemaForm.vue';import ResultView from './ResultView.vue';import Records from './Records.vue';
const props=defineProps<{project:any,admin:boolean,baseURL:string}>();const emit=defineEmits(['message','changed','back']);
const tab=ref('services'),services=ref<any[]>([]),devices=ref<any[]>([]),users=ref<any[]>([]),tokens=ref<any[]>([]),docs=ref(''),openapi=ref(''),edit=ref<any>(null),invoke=ref<any>(null),params=ref<any>({}),result=ref<any>(null),error=ref(''),busy=ref(false),newToken=ref(false),tokenName=ref(''),tokenExpiry=ref(''),scopes=ref(['docs:read','services:read','services:invoke']),secret=ref(''),copyText=ref(''),members=ref<string[]>([]),auto=ref(false),intervalSeconds=ref(10);
let timer:ReturnType<typeof setInterval>|undefined;
const chosenDevice=computed(()=>devices.value.find(d=>d.id===edit.value?.device_id));const chosenService=computed(()=>chosenDevice.value?.services.find((s:any)=>s.key===edit.value?.device_service_key));
const examples=computed(()=>Array.from(docs.value.matchAll(/```sh\n([\s\S]*?)```/g)).map(m=>m[1]).join('\n'));
const docsURL=computed(()=>props.baseURL+'/api/v1/projects/'+props.project.key+'/docs');
async function load(){try{services.value=await api(props.admin?`/admin/projects/${props.project.id}/services`:`/projects/${props.project.key}/services`);members.value=[...(props.project.member_ids||[])];if(props.admin)[devices.value,users.value,tokens.value]=await Promise.all([api('/admin/devices'),api('/admin/users'),api(`/admin/projects/${props.project.id}/tokens`)])}catch(e:any){emit('message',e.code+'：'+e.message)}}
onMounted(load);watch(()=>props.project.id,()=>{tab.value='services';stopAuto();load()});
async function selectTab(t:string){tab.value=t;stopAuto();if(t==='docs'){try{[docs.value,openapi.value]=await Promise.all([api(`/projects/${props.project.key}/docs`),api(`/projects/${props.project.key}/openapi.json`).then(v=>JSON.stringify(v,null,2))])}catch(e:any){emit('message',e.message)}}}
function create(){error.value='';edit.value={key:'',display_name:'',description:'',usage_instructions:'',device_id:'',device_service_key:'',default_parameters:{},parameter_constraints:{},enabled:true}}
function editing(b:any){error.value='';edit.value=JSON.parse(JSON.stringify(b))}
function deviceChange(){edit.value.device_service_key='';edit.value.default_parameters={};edit.value.parameter_constraints={}}
function serviceChange(){edit.value.default_parameters={};edit.value.parameter_constraints={}}
function constraint(key:string,kind:string,value:string){const map=edit.value.parameter_constraints;map[key]={...(map[key]||{})};if(value==='')delete map[key][kind];else map[key][kind]=Number(value);if(!Object.keys(map[key]).length)delete map[key]}
async function save(){busy.value=true;error.value='';try{const b=edit.value;await api(`/admin/projects/${props.project.id}/services`+(b.id?'/'+b.id:''),b.id?'PATCH':'POST',b);edit.value=null;await load();emit('changed')}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function enable(b:any){try{await api(`/admin/projects/${props.project.id}/services/${b.id}`,'PATCH',{...b,enabled:!b.enabled});await load();emit('changed')}catch(e:any){emit('message',e.message)}}
async function remove(b:any){if(!await ask('删除服务“'+b.display_name+'”？原调用URL将失效，服务key保留且不能复用；设备输出不会改变。'))return;try{await api(`/admin/projects/${props.project.id}/services/${b.id}`,'DELETE');await load();emit('changed')}catch(e:any){emit('message',e.message)}}
function startCall(b:any){stopAuto();invoke.value=b;params.value={...b.default_parameters};result.value=null;error.value=''}
async function execute(){if(busy.value||!invoke.value||document.hidden)return;busy.value=true;error.value='';try{result.value=await api(`/projects/${props.project.key}/services/${invoke.value.key}/invoke`,'POST',{parameters:params.value})}catch(e:any){error.value=e.code+'：'+e.message;if(e instanceof ApiError)result.value=e.record;stopAuto()}finally{busy.value=false}}
function stopAuto(){auto.value=false;if(timer)clearInterval(timer);timer=undefined}
function configureAuto(){if(timer)clearInterval(timer);timer=undefined;if(auto.value&&invoke.value?.service_contract.kind==='read'){intervalSeconds.value=Math.max(5,intervalSeconds.value);timer=setInterval(()=>{if(!document.hidden)execute()},intervalSeconds.value*1000)}}
function visibility(){if(document.hidden)stopAuto()}document.addEventListener('visibilitychange',visibility);onUnmounted(()=>{stopAuto();document.removeEventListener('visibilitychange',visibility)});
async function copy(value:string){try{if(!navigator.clipboard)throw Error();await navigator.clipboard.writeText(value);emit('message','已复制')}catch{copyText.value=value}}
function download(text:string,filename:string,type:string){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}
async function createToken(){busy.value=true;error.value='';try{const r=await api(`/admin/projects/${props.project.id}/tokens`,'POST',{name:tokenName.value,scopes:scopes.value,expires_at:tokenExpiry.value?new Date(tokenExpiry.value).toISOString():null});newToken.value=false;secret.value=r.secret;await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function revoke(t:any){if(!await ask('撤销Token“'+t.name+'”？使用它的后续请求将立即被拒绝。'))return;try{await api(`/admin/projects/${props.project.id}/tokens/${t.id}`,'DELETE');await load()}catch(e:any){emit('message',e.message)}}
async function saveMembers(){busy.value=true;try{await api(`/admin/projects/${props.project.id}/members`,'PUT',{member_ids:members.value,revision:props.project.revision});emit('changed');emit('message','项目成员已更新')}catch(e:any){emit('message',e.message)}finally{busy.value=false}}
</script>
<template><section><button class="text-button back" @click="emit('back')">← 返回项目列表</button><div class="section-title"><div><p class="eyebrow">PROJECT / {{project.key}}</p><h1>{{project.display_name}}</h1><p class="muted">{{project.purpose||'尚未填写项目用途'}}</p></div><span class="badge" :class="project.enabled?'online':'error'">{{project.enabled?'项目已启用':'项目已禁用'}}</span></div><div v-if="!project.enabled" class="notice">项目已禁用，对外调用与文档访问暂停。</div><nav class="tabs" aria-label="项目页面"><button v-for="t in [{key:'services',label:'项目服务'},{key:'docs',label:'项目文档'},{key:'records',label:'调用记录'},...(admin?[{key:'tokens',label:'Access Token'},{key:'members',label:'项目成员'}]:[])]" :key="t.key" :class="{active:tab===t.key}" @click="selectTab(t.key)">{{t.label}}</button></nav>
<div v-if="tab==='services'"><div class="row spread section-tools"><p class="muted">{{services.length}} 项服务 · 使用稳定名称调用设备能力</p><button v-if="admin" class="primary" @click="create">＋ 添加项目服务</button></div><div v-if="!services.length" class="empty"><h2>定义项目的第一项服务</h2><p>为设备能力起一个业务名称，调用方无需了解底层连接。</p><button v-if="admin" @click="create">添加项目服务</button></div><div class="service-list"><article v-for="b in services" :key="b.id" class="card service-card"><div class="row spread"><div><span class="badge">{{b.service_contract.kind==='read'?'采集':'操作'}}</span><h2>{{b.display_name}}</h2><code>{{b.key}}</code></div><span class="badge" :class="b.enabled&&b.binding_state==='valid'?'online':'error'">{{!b.enabled?'已禁用':b.binding_state==='valid'?'可调用':b.binding_state==='unbound'?'未绑定':'绑定失效'}}</span></div><p>{{b.description||'暂无用途说明'}}</p><p v-if="b.usage_instructions" class="muted small">{{b.usage_instructions}}</p><div class="card-actions"><button class="primary" :disabled="!project.enabled||!b.enabled||b.binding_state!=='valid'" @click="startCall(b)">手动调用</button><template v-if="admin"><button @click="editing(b)">编辑服务</button><button @click="enable(b)">{{b.enabled?'停用':'启用'}}</button><button class="danger text-button" @click="remove(b)">删除</button></template></div></article></div></div>
<div v-if="tab==='docs'" class="card"><div class="row wrap"><button @click="copy(docsURL)">复制文档 URL</button><button @click="copy(examples)" :disabled="!examples">复制调用示例</button><button @click="download(docs,project.key+'.md','text/markdown')" :disabled="!docs">下载 Markdown</button><button @click="download(openapi,project.key+'-openapi.json','application/json')" :disabled="!openapi">下载 OpenAPI</button></div><p class="meta">文档从当前服务定义生成。Token另行分配，文档中只包含凭据占位符。</p><pre class="document" data-testid="project-document">{{docs}}</pre><details><summary>查看 OpenAPI</summary><pre>{{openapi}}</pre></details></div>
<Records v-if="tab==='records'" :project="project" :admin="admin" @message="emit('message',$event)"/>
<div v-if="tab==='tokens'"><div class="row spread section-tools"><p class="muted">仅授权当前项目，原文只在创建时展示一次。</p><button class="primary" @click="newToken=true;tokenName='';tokenExpiry='';scopes=['docs:read','services:read','services:invoke'];error=''">＋ 创建 Token</button></div><div v-if="!tokens.length" class="empty compact">尚未创建 Token</div><div class="card-grid"><article v-for="t in tokens" :key="t.id" class="card"><div class="row spread"><h2>{{t.name}}</h2><span class="badge" :class="t.enabled?'online':'error'">{{!t.enabled?'已撤销':t.expires_at&&new Date(t.expires_at)<new Date()?'已到期':'有效'}}</span></div><p><code>{{t.prefix}}…</code></p><p class="meta">{{t.scopes.join(' · ')}}<br>到期：{{t.expires_at?new Date(t.expires_at).toLocaleString():'不设到期时间'}}</p><button v-if="t.enabled" class="danger" @click="revoke(t)">撤销 Token</button></article></div></div>
<form v-if="tab==='members'" class="card narrow" @submit.prevent="saveMembers"><h2>项目成员</h2><p class="muted">成员可查看文档、调用服务和查看本项目记录。管理员始终拥有管理权限。</p><label v-for="u in users.filter(u=>u.role==='member')" :key="u.id" class="check-row"><input v-model="members" type="checkbox" :value="u.id">{{u.username}} {{u.enabled?'':'（已禁用）'}}</label><p v-if="!users.some(u=>u.role==='member')" class="muted">请先在用户管理中创建普通用户。</p><button class="primary" :disabled="busy">保存项目成员</button></form>
<Dialog v-if="edit" :title="edit.id?'编辑项目服务':'添加项目服务'" @close="if(!busy)edit=null;"><form @submit.prevent="save"><div class="two-columns"><label>服务标识<input v-model="edit.key" required pattern="[a-z](?:[a-z0-9_]|-){0,63}" :disabled="!!edit.id" placeholder="board_power"></label><label>显示名称<input v-model="edit.display_name" required placeholder="板卡上下电"></label></div><label>用途说明<textarea v-model="edit.description" rows="2"/></label><label>使用说明<textarea v-model="edit.usage_instructions" rows="2"/></label><label>绑定设备<select v-model="edit.device_id" @change="deviceChange"><option value="">暂不绑定</option><option v-for="d in devices" :key="d.id" :value="d.id">{{d.display_name}}</option></select></label><label v-if="chosenDevice">设备服务<select v-model="edit.device_service_key" required @change="serviceChange"><option value="">选择设备服务</option><option v-for="s in chosenDevice.services" :key="s.key" :value="s.key">{{s.title}} · {{s.key}}</option></select></label><template v-if="chosenService"><h3>项目默认参数（可留空）</h3><SchemaForm :schema="{...chosenService.input_schema,required:[]}" v-model="edit.default_parameters" prefix="default"/><template v-for="(field,key) in chosenService.input_schema.properties" :key="key"><fieldset v-if="field.type==='number'||field.type==='integer'"><legend>{{field.unit==='V'?'电压':field.unit==='A'?'电流限值':key}}的项目范围</legend><div class="two-columns"><label>下限<input type="number" step="any" :min="field.minimum" :max="field.maximum" :value="edit.parameter_constraints[key]?.minimum??''" placeholder="沿用设备范围" @input="constraint(String(key),'minimum',($event.target as HTMLInputElement).value)"></label><label>上限<input type="number" step="any" :min="field.minimum" :max="field.maximum" :value="edit.parameter_constraints[key]?.maximum??''" placeholder="沿用设备范围" @input="constraint(String(key),'maximum',($event.target as HTMLInputElement).value)"></label></div></fieldset></template></template><label class="check-row"><input v-model="edit.enabled" type="checkbox">启用服务</label><p v-if="error" class="error-text" role="alert">{{error}}</p><footer class="form-actions"><button type="button" @click="edit=null" :disabled="busy">取消</button><button class="primary" :disabled="busy">保存服务</button></footer></form></Dialog>
<Dialog v-if="invoke" :title="invoke.display_name+' · 手动调用'" @close="if(!busy){stopAuto();invoke=null};"><form @submit.prevent="execute"><p class="muted">{{invoke.usage_instructions||invoke.description}}</p><SchemaForm :schema="invoke.service_contract.input_schema" v-model="params" prefix="invoke"/><div v-if="invoke.service_contract.kind==='read'" class="refresh-options"><label class="check-row"><input v-model="auto" type="checkbox" @change="configureAuto">开启自动刷新</label><label>刷新间隔（秒，至少5秒）<input v-model.number="intervalSeconds" type="number" min="5" max="3600" @change="configureAuto"></label><small class="muted">页面隐藏或读取失败时停止，不自动重试失败请求。</small></div><p v-else class="notice">此操作会修改实际设备。成功以回读确认，超时可能表示结果未知。</p><p v-if="error" class="error-text" role="alert">{{error}}</p><button class="primary" :disabled="busy">{{busy?'通信中…':'执行调用'}}</button></form><ResultView :record="result"/></Dialog>
<Dialog v-if="newToken" title="创建项目 Token" @close="if(!busy)newToken=false;"><form @submit.prevent="createToken"><label>Token 名称<input v-model="tokenName" required placeholder="开发 Agent"></label><label>到期时间（可选）<input v-model="tokenExpiry" type="datetime-local"></label><fieldset><legend>作用域</legend><label v-for="s in [{key:'docs:read',label:'读取项目文档'},{key:'services:read',label:'读取服务列表'},{key:'services:invoke',label:'调用项目服务'}]" :key="s.key" class="check-row"><input v-model="scopes" type="checkbox" :value="s.key">{{s.label}}</label></fieldset><p v-if="error" class="error-text" role="alert">{{error}}</p><footer class="form-actions"><button class="primary" :disabled="busy||!scopes.length">创建 Token</button></footer></form></Dialog>
<Dialog v-if="secret" title="请保存 Token 原文" @close="secret=''"><p class="notice">原文只展示这一次。关闭后无法再次查看，请单独交给调用方。</p><label>Access Token<textarea :value="secret" readonly rows="4" @focus="($event.target as HTMLTextAreaElement).select()"/></label><div class="form-actions"><button @click="copy(secret)">复制 Token</button><button class="primary" @click="secret=''">已保存，关闭</button></div></Dialog>
<Dialog v-if="copyText" title="手动复制" @close="copyText=''"><p>浏览器未允许自动复制，请选择下方文本后复制。</p><textarea :value="copyText" readonly rows="7" @focus="($event.target as HTMLTextAreaElement).select()"/><footer class="form-actions"><button @click="copyText=''">完成</button></footer></Dialog>
</section></template>
